const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;padding:12px;display:flex;flex-direction:column;min-width:0;min-height:0;overflow:hidden;color:var(--ink);font-size:13px;line-height:1.45}\n.card *{box-sizing:border-box}\n.view{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px}\n.head{flex:none;display:flex;flex-direction:column;gap:1px;min-width:0}\n.ttl{display:flex;align-items:center;gap:6px;font-size:15px;font-weight:700;color:var(--ink)}\n.ttl::before{content:\"\";flex:none;width:4px;height:14px;border-radius:2px;background:var(--accent)}\n.sub{font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.focus,.empty{flex:1 1 0;min-height:0;min-width:0;background:var(--soft);border-radius:12px;padding:10px;display:flex;flex-direction:column;gap:7px}\n.focus{overflow:auto;cursor:pointer}\n.focus:focus-visible,.lrow:focus-visible,.rrow:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.empty{justify-content:center;gap:4px}\n.empty-t{font-weight:700}\n.empty-s{font-size:12px;color:var(--muted)}\n.item{flex:none;display:flex;gap:8px;align-items:flex-start;min-width:0}\n.n{flex:none;width:18px;height:18px;margin-top:1px;border-radius:50%;background:var(--accent);color:var(--on-accent);font-size:11px;font-weight:700;display:grid;place-items:center}\n.t{min-width:0;overflow-wrap:anywhere;word-break:break-word}\n.none{color:var(--muted)}\n.acts{flex:none;display:flex;gap:8px;min-width:0}\n.acts .btn{flex:1 1 0}\n.acts .btn.primary{flex:2 1 0}\n.acts.col{flex-direction:column}\n.acts.col .btn{flex:none}\n.btn{min-width:0;height:34px;padding:0 8px;border-radius:10px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font:inherit;font-size:13px;cursor:pointer;white-space:nowrap}\n.btn.primary{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn.mini{height:26px;padding:0 8px;font-size:12px;flex:none}\n.btn:disabled{opacity:.5;cursor:default}\n.btn:focus-visible,.ibtn:focus-visible,.ta:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.ibtn{flex:none;width:30px;height:30px;padding:0;border-radius:50%;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font:inherit;font-size:16px;line-height:1;cursor:pointer}\n.ibtn:disabled{opacity:.35;cursor:default}\n.tag{flex:none;font-size:10px;line-height:16px;padding:0 6px;border-radius:8px;background:var(--accent);color:var(--on-accent);font-weight:600}\n.home .main{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:8px}\n.home .side{flex:none;width:112px;display:flex;flex-direction:column;justify-content:flex-end;gap:10px}\n.stat{font-size:12px;color:var(--muted);display:flex;flex-direction:column;gap:2px}\n.card[data-size=\"6x3\"] .home{flex-direction:row;gap:12px}\n.rec{flex:none;display:flex;flex-direction:column;gap:2px}\n.rt{font-size:11px;font-weight:700;color:var(--muted);margin-bottom:2px}\n.rrow{display:flex;gap:6px;align-items:center;min-width:0;padding:5px 4px;border-bottom:1px solid var(--line);cursor:pointer}\n.rw{flex:none;font-weight:600}\n.rs{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted);font-size:12px}\n\n.hist.wide{flex-direction:row;gap:10px}\n.lpane{display:flex;flex-direction:column;gap:6px;min-width:0;min-height:0;flex:1}\n.hist.wide .lpane{flex:none;width:128px}\n.lhead{flex:none;display:flex;align-items:center;gap:8px;min-width:0}\n.lt{font-weight:700;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.scroll{flex:1 1 0;min-height:0;min-width:0;overflow:auto}\n.lrows{display:flex;flex-direction:column;gap:2px}\n.lrow{flex:none;display:flex;flex-direction:column;gap:1px;min-width:0;padding:6px 8px;border-radius:10px;border:1px solid transparent;cursor:pointer}\n.lrow.on{background:var(--soft);border-color:var(--line)}\n.lw{display:flex;align-items:center;gap:6px;font-weight:600;white-space:nowrap}\n.ls{font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.dpane{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:8px}\n.dnav{flex:none;display:flex;align-items:center;gap:4px;min-width:0}\n.dttl{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;line-height:1.2;gap:2px}\n.dttl .wk{font-weight:700;white-space:nowrap}\n.dbody{background:var(--soft);border-radius:12px;padding:10px;display:flex;flex-direction:column;gap:10px}\n.sec{flex:none;min-width:0}\n.sl{font-size:11px;font-weight:700;color:var(--muted);margin-bottom:2px}\n.st{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word}\n.dl{display:flex;flex-direction:column;gap:6px}\n.upd{flex:none;font-size:11px;color:var(--muted)}\n.dfoot{flex:none;display:flex;flex-direction:column;gap:6px;min-width:0}\n.warn,.err{font-size:12px;color:var(--ink);overflow-wrap:anywhere}\n.err{font-weight:600}\n.note{flex:none;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:12px;padding:4px 8px;border-radius:10px;background:var(--soft);min-width:0}\n.fields{flex:1 1 0;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:8px}\n.fld{flex:none;display:flex;flex-direction:column;gap:3px;min-width:0}\n.fl{font-size:11px;font-weight:700;color:var(--muted)}\n.ta{display:block;width:100%;min-height:64px;flex:1 1 auto;resize:none;padding:7px 9px;border-radius:10px;border:1px solid var(--line);background:var(--paper);color:var(--ink);font:inherit;font-size:13px;line-height:1.45}\n.ta::placeholder{color:var(--muted)}\n.card[data-size=\"3x6\"] .fld,.card[data-size=\"6x6\"] .fld{flex:1 1 0;min-height:88px}\n.card[data-size=\"3x6\"] .ta,.card[data-size=\"6x6\"] .ta{flex:1 1 0;min-height:0}\n.card[data-size=\"6x3\"] .fields{flex-direction:row}\n.card[data-size=\"6x3\"] .fld{flex:1 1 0}\n.card[data-size=\"6x3\"] .ta{flex:1 1 0;min-height:44px}\n";
const DAY_MS=86400000;
function dnum(s){const p=String(s).split('-');return Math.round(Date.UTC(+p[0],(+p[1])-1,+p[2])/DAY_MS);}
function dstr(n){const d=new Date(n*DAY_MS);const m=d.getUTCMonth()+1;const x=d.getUTCDate();return d.getUTCFullYear()+'-'+(m<10?'0':'')+m+'-'+(x<10?'0':'')+x;}
function mondayOf(s){const n=dnum(s);const dow=(((n+4)%7)+7)%7;return dstr(n-((dow+6)%7));}
function addWeeks(w,k){return dstr(dnum(w)+7*k);}
function weekShort(w,curYear){
  const n=dnum(w);const a=new Date(n*DAY_MS);const b=new Date((n+6)*DAY_MS);
  const y=a.getUTCFullYear();
  return (y!==curYear?y+'/':'')+(a.getUTCMonth()+1)+'/'+a.getUTCDate()+'–'+(b.getUTCMonth()+1)+'/'+b.getUTCDate();
}
function weeksAgo(cur,w){return (dnum(cur)-dnum(w))/7;}
function relName(k){return k===0?'本周':(k===1?'上周':'');}
function lines(t){return String(t||'').split('\n').map(x=>x.replace(/^\s*[-•·*]\s*/,'').trim()).filter(Boolean);}
function firstLine(t){const l=lines(t);return l.length?l[0]:'';}
function toDraft(r,week){return r?{id:r.id,week:r.week,progress:r.progress||'',difficulty:r.difficulty||'',adjust:r.adjust||''}:{id:'',week:week,progress:'',difficulty:'',adjust:''};}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day}=ctx;
  const size=ctx.size||'3x3';
  const wide=size==='6x3'||size==='6x6';
  const today=day();
  const cur=mondayOf(today);
  const curYear=Number(today.slice(0,4));
  const list=(state&&Array.isArray(state.reviews)?state.reviews:[]).filter(r=>r&&r.id&&r.week).slice();
  list.sort((a,b)=>a.week<b.week?1:(a.week>b.week?-1:0));
  const wk=w=>weekShort(w,curYear);
  const hasCur=list.some(r=>r.week===cur);
  function go(patch){Object.assign(ui,patch);redraw();}
  function kids(a){return a.filter(Boolean);}
  function btn(label,onClick,cls,extra){return el('button',Object.assign({type:'button',class:'btn'+(cls?' '+cls:''),onclick:onClick},extra||{}),label);}
  function tagOf(w){const n=relName(weeksAgo(cur,w));return n?el('span',{class:'tag'},n):null;}
  function numItem(t,i){return el('div',{class:'item'},el('span',{class:'n'},String(i+1)),el('span',{class:'t'},t));}
  function openHistory(id){go({view:'history',sel:id||null,err:'',delId:''});}

  function homeView(){
    const r=list[0];
    const k=r?weeksAgo(cur,r.week):0;
    const ttl=!r?'每周复盘':(k<=0?'下周重点':(k===1?'本周重点':'上次定下的重点'));
    const sub=r?'来自 '+(relName(k)?relName(k)+' · ':'')+wk(r.week)+' 复盘':'记录进步、困难与下周调整';
    const head=el('div',{class:'head'},el('div',{class:'ttl'},ttl),el('div',{class:'sub'},sub));
    let focus;
    if(!r){
      focus=el('div',{class:'empty'},el('div',{class:'empty-t'},'还没有复盘记录'),el('div',{class:'empty-s'},'每周写下进步、遇到的困难和下周要调整的事；写好后这里会显示下周重点。'));
    }else{
      const items=lines(r.adjust);
      const rows=items.length?items.map(numItem):[el('div',{class:'none'},'这一周没有写下周要调整的事')];
      focus=el('div',{class:'focus',role:'button',tabindex:'0','aria-label':'查看历史复盘',
        onclick:()=>openHistory(r.id),
        onkeydown:e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openHistory(r.id);}}},...rows);
    }
    const label=!list.length?'写第一份复盘':(hasCur?'改本周复盘':'写本周复盘');
    const acts=el('div',{class:'acts'+(size==='6x3'?' col':'')},...kids([
      btn(label,()=>openEditor(cur,null,'home'),'primary'),
      list.length?btn('历史',()=>openHistory(null)):null]));
    function recent(n,snip){
      const rows=list.slice(0,n).map(x=>el('div',{class:'rrow',role:'button',tabindex:'0',onclick:()=>openHistory(x.id)},...kids([
        el('span',{class:'rw'},wk(x.week)),tagOf(x.week),
        snip?el('span',{class:'rs'},firstLine(x.progress)||'（未写进步）'):null])));
      return el('div',{class:'rec'},el('div',{class:'rt'},'最近复盘'),...rows);
    }
    if(size==='6x3'){
      const stat=el('div',{class:'stat'},
        el('div',{},list.length?'已记录 '+list.length+' 周':'暂无记录'),
        el('div',{},hasCur?'本周已复盘':'本周还没复盘'));
      return el('div',{class:'view home'},el('div',{class:'main'},head,focus),el('div',{class:'side'},stat,acts));
    }
    const extra=!list.length?null:(size==='3x6'?recent(4,false):(size==='6x6'?recent(4,true):null));
    return el('div',{class:'view home'},...kids([head,focus,extra,acts]));
  }


  function listPane(sel){
    const lhead=el('div',{class:'lhead'},
      el('button',{type:'button',class:'ibtn','aria-label':'返回首页',onclick:()=>go({view:'home',sel:null,delId:'',err:''})},'←'),
      el('div',{class:'lt'},wide?'共 '+list.length+' 周':'历史复盘 · 共 '+list.length+' 周'));
    const rows=list.map(x=>el('div',{class:'lrow'+(sel&&sel.id===x.id?' on':''),role:'button',tabindex:'0',
      onclick:()=>go({sel:x.id,delId:'',err:''})},
      el('div',{class:'lw'},el('span',{},wk(x.week)),tagOf(x.week)),
      el('div',{class:'ls'},firstLine(x.progress)||firstLine(x.adjust)||'（空）')));
    return el('div',{class:'lpane'},lhead,el('div',{class:'scroll lrows'},...rows));
  }

  async function del(id,i){
    const nxt=list[i+1]||list[i-1]||null;
    try{
      await commit(s=>Object.assign({},s,{reviews:(s&&Array.isArray(s.reviews)?s.reviews:[]).filter(x=>x.id!==id)}),
        Object.assign({},ui,{view:nxt?'history':'home',sel:nxt?nxt.id:null,delId:'',err:''}));
    }catch(e){
      ui.delId='';ui.err='删除失败：'+(e&&e.message?e.message:'请稍后重试');redraw();
    }
  }

  function detailPane(r){
    const i=list.findIndex(x=>x.id===r.id);
    const older=list[i+1];
    const newer=list[i-1];
    const nav=el('div',{class:'dnav'},
      el('button',{type:'button',class:'ibtn','aria-label':'更早的一周',disabled:!older,onclick:()=>{if(older)go({sel:older.id,delId:'',err:''});}},'‹'),
      el('div',{class:'dttl'},...kids([el('span',{class:'wk'},wk(r.week)),tagOf(r.week)])),
      el('button',{type:'button',class:'ibtn','aria-label':'更近的一周',disabled:!newer,onclick:()=>{if(newer)go({sel:newer.id,delId:'',err:''});}},'›'));
    const sec=(lab,txt,asList)=>{
      const ls=lines(txt);
      let body;
      if(!ls.length)body=el('div',{class:'none'},'未填写');
      else if(asList)body=el('div',{class:'dl'},...ls.map(numItem));
      else body=el('div',{class:'st'},String(txt).trim());
      return el('div',{class:'sec'},el('div',{class:'sl'},lab),body);
    };
    const body=el('div',{class:'scroll dbody'},...kids([
      sec('这周的进步',r.progress,false),
      sec('遇到的困难',r.difficulty,false),
      sec('下周要调整的事',r.adjust,true),
      r.updated?el('div',{class:'upd'},'更新于 '+r.updated):null]));
    let foot;
    if(ui.delId===r.id){
      foot=el('div',{class:'dfoot'},
        el('div',{class:'warn'},'确定删除这一周的复盘？删除后无法恢复。'),
        el('div',{class:'acts'},btn('取消',()=>go({delId:''})),btn('确认删除',()=>del(r.id,i),'primary')));
    }else{
      foot=el('div',{class:'dfoot'},...kids([
        ui.err?el('div',{class:'err'},'提示：'+ui.err):null,
        el('div',{class:'acts'},...kids([
          wide?null:btn('列表',()=>go({sel:null,delId:'',err:''})),
          btn('编辑',()=>openEditor(r.week,r,'history')),
          btn('删除',()=>go({delId:r.id,err:''}))]))]));
    }
    return el('div',{class:'dpane'},nav,body,foot);
  }

  function historyView(){
    let sel=list.find(x=>x.id===ui.sel)||null;
    if(wide&&!sel)sel=list[0];
    if(wide)return el('div',{class:'view hist wide'},listPane(sel),detailPane(sel));
    return el('div',{class:'view hist'},sel?detailPane(sel):listPane(null));
  }


  function openEditor(week,rec,from){
    go({view:'edit',from:from||'home',err:'',saving:false,delId:'',draft:toDraft(rec||list.find(x=>x.week===week)||null,week)});
  }
  function closeEditor(){
    go({view:(ui.from==='history'&&list.length)?'history':'home',draft:null,err:'',saving:false});
  }

  async function save(){
    const d=ui.draft;
    if(!d||ui.saving)return;
    const rec={progress:d.progress.trim(),difficulty:d.difficulty.trim(),adjust:d.adjust.trim()};
    if(!rec.progress&&!rec.difficulty&&!rec.adjust){ui.err='三项至少写一项再保存';redraw();return;}
    if(list.some(x=>x.week===d.week&&x.id!==d.id)){ui.err='这一周已有复盘记录';redraw();return;}
    const id=d.id||uid();
    const week=d.week;
    const back=ui.from==='history'?{view:'history',sel:id}:{view:'home',sel:null};
    ui.saving=true;ui.err='';redraw();
    try{
      await commit(s=>{
        const rs=s&&Array.isArray(s.reviews)?s.reviews:[];
        if(rs.some(x=>x.week===week&&x.id!==id))throw new Error('这一周已有复盘记录');
        const row={id:id,week:week,progress:rec.progress,difficulty:rec.difficulty,adjust:rec.adjust,updated:today};
        const has=rs.some(x=>x.id===id);
        return Object.assign({},s,{reviews:has?rs.map(x=>x.id===id?Object.assign({},x,row):x):rs.concat([row])});
      },Object.assign({},ui,back,{draft:null,saving:false,err:'',delId:''}));
    }catch(e){
      ui.saving=false;ui.err='保存失败：'+(e&&e.message?e.message:'请稍后重试');redraw();
    }
  }

  function editorView(){
    const d=ui.draft;
    const conflict=list.find(x=>x.week===d.week&&x.id!==d.id)||null;
    const step=k=>{d.week=addWeeks(d.week,k);ui.err='';redraw();};
    const nav=el('div',{class:'dnav'},
      el('button',{type:'button',class:'ibtn','aria-label':'前一周',onclick:()=>step(-1)},'‹'),
      el('div',{class:'dttl'},...kids([el('span',{class:'wk'},wk(d.week)),tagOf(d.week)])),
      el('button',{type:'button',class:'ibtn','aria-label':'后一周',disabled:dnum(d.week)>=dnum(cur),onclick:()=>step(1)},'›'));
    const field=(key,label,ph)=>el('label',{class:'fld'},
      el('span',{class:'fl'},label),
      el('textarea',{class:'ta',value:d[key],placeholder:ph,'aria-label':label,oninput:e=>{d[key]=e.target.value;}}));
    const note=conflict?el('div',{class:'note'},el('span',{},'这一周已有记录'),btn('载入编辑',()=>go({draft:toDraft(conflict),err:''}),'mini')):null;
    const err=ui.err?el('div',{class:'err'},'提示：'+ui.err):null;
    const foot=el('div',{class:'acts'},btn('取消',closeEditor),btn(ui.saving?'保存中…':'保存',save,'primary',{disabled:!!conflict||!!ui.saving}));
    return el('div',{class:'view edit'},...kids([nav,note,
      el('div',{class:'fields'},
        field('progress','这周的进步','做成了什么、哪里有进展'),
        field('difficulty','遇到的困难','卡在哪里、什么拖慢了你'),
        field('adjust','下周要调整的事','一行写一件，首页显示为下周重点')),
      err,foot]));
  }

  let v=ui.view||'home';
  if(v==='history'&&!list.length)v='home';
  if(v==='edit'&&!ui.draft)v='home';
  root.append(v==='edit'?editorView():(v==='history'?historyView():homeView()));
}

const RUNTIME_BUILD='v50-r22-theme-20261102';
const INFRA_CSS=`:host{display:block;width:100%;height:100%}*{box-sizing:border-box}.card{width:100%;height:100%;position:relative;container:card / size;min-width:0;min-height:0;overflow:auto}button,input,textarea,select{font:inherit}button{cursor:pointer;touch-action:manipulation}.infra-panel{position:absolute;inset:0;z-index:100;display:grid;grid-template-rows:auto minmax(0,1fr) auto;gap:10px;padding:12px;background:var(--panel-paper);color:var(--ink);overflow:hidden;font:13px/1.4 system-ui}.infra-head{display:flex;align-items:center;justify-content:space-between;gap:8px}.infra-content{overflow:auto;min-height:0}.infra-actions{display:flex;gap:6px;flex-wrap:wrap}.infra-panel button{border:1px solid var(--line);border-radius:8px;padding:7px 10px;background:var(--button-paper);color:inherit}.infra-panel button[data-primary]{background:var(--accent);color:var(--on-accent)}.infra-form{display:grid;gap:10px}.infra-form label{display:grid;gap:4px}.infra-form input:not([type=checkbox]),.infra-form textarea,.infra-form select{width:100%;min-width:0;padding:8px;border:1px solid var(--line);border-radius:7px;background:var(--panel-paper);color:inherit}.infra-error{color:var(--danger);font-size:12px}.infra-form textarea{min-height:65px}`;
export default class Card extends HTMLElement{
 constructor(){super();this.attachShadow({mode:'open'});this.state={};this.ui={};this.queue=Promise.resolve();this.epoch=0;this.pending=0;}
 set tabbitHost(h){this.host=h;if(this.isConnected)this.load();}
 connectedCallback(){if(this.host)this.load();}
 disconnectedCallback(){this.epoch++;this.stop();}
 destroy(){this.disconnectedCallback();}
